"""Compile actual NPC talk/amount/inn handlers with controlled world and inventory stubs.
No live MySQL or room-capacity concurrency simulation."""
from pathlib import Path
import tempfile, subprocess
root=Path(__file__).resolve().parents[2]
base='l1j/server/server/'
P='model/network/core/cs/packet/'
with tempfile.TemporaryDirectory() as td:
    src=Path(td)/'src'; out=Path(td)/'out'; out.mkdir()
    def put(path,body):
        f=src/path; f.parent.mkdir(parents=True,exist_ok=True); f.write_text(body,encoding='utf-8')
    def w(path,body): put(base+path+'.java',body)
    def copy(path): put(path,(root/'src'/path).read_text(encoding='utf-8'))
    for name in ['CS_Amount','NpcTalkHandler']: copy(base+P+name+'.java')
    copy('l1j/server/server/model/world/instance/inn/InnHelper.java')
    text=(root/'src'/base/P/'HtmlCmdHandler.java').read_text()
    def method(name):
        i=text.index('    static boolean '+name+'('); start=text.index('{',i); depth=1; j=start+1
        while depth:
            if text[j]=='{': depth+=1
            elif text[j]=='}': depth-=1
            j+=1
        return text[i:j]
    w(P+'HtmlCmdHandler','''package l1j.server.server.model.network.core.cs.packet;
import l1j.server.server.model.network.core.session.CIOClient;import l1j.server.server.model.network.utill.ConnectionState;import l1j.server.server.model.Instance.*;
final class HtmlCmdHandler {'''+method('canInteractWithNpc')+method('isNpcTargetInRange')+ '}')
    w('model/L1Object','''package l1j.server.server.model;import l1j.server.server.model.Instance.*;public class L1Object {public int id=1; public int getId(){return id;}public void onTalkAction(L1PcInstance pc){pc.talks++;}}''')
    w('model/L1World','''package l1j.server.server.model;import java.util.*;public class L1World {public static L1World world=new L1World();public Map<Integer,L1Object> objects=new HashMap<>();public static L1World getInstance(){return world;}public L1Object findObject(int id){return objects.get(id);}public void removeObject(L1Object o){objects.remove(o.id,o);}}''')
    w('model/Instance/L1NpcInstance','''package l1j.server.server.model.Instance;import l1j.server.server.model.*;public class L1NpcInstance extends L1Object {public int x=100,y=100,map=1,npcId=99;public int getX(){return x;}public int getY(){return y;}public int getMapId(){return map;}public int getNpcId(){return npcId;}public L1NpcInstance getNpcTemplate(){return this;}public int get_npcId(){return npcId;}public String getName(){return "inn";}}''')
    w('model/Instance/L1AuctionBoardInstance','''package l1j.server.server.model.Instance;public class L1AuctionBoardInstance extends L1NpcInstance {}''')
    w('model/Instance/L1ItemInstance','''package l1j.server.server.model.Instance;import l1j.server.server.model.*;public class L1ItemInstance extends L1Object {public boolean stack;public boolean isStackable(){return stack;}}''')
    w('model/Instance/L1PcInstance','''package l1j.server.server.model.Instance;import l1j.server.server.model.*;import l1j.server.server.model.network.core.session.*;public class L1PcInstance extends L1Object {public int x=100,y=100,map=1,talks,bids,sells,xml,inn,notice;public boolean ghost,shop,unattended,autoclan,busy,crown;public L1Inventory inv=new L1Inventory(); public CIOClient net;public int getX(){return x;}public int getY(){return y;}public int getMapId(){return map;}public boolean isGhost(){return ghost;}public boolean isPrivateShop(){return shop;}public boolean is무인상점(){return unattended;}public boolean isAutoClanjoin(){return autoclan;}public boolean isItemTransferBusy(){return busy;}public boolean isCrown(){return crown;}public L1Inventory getInventory(){return inv;}public int getLawful(){return 0;}public boolean isOnTargetEffect(){return false;}public long getLastNpcClickMs(){return 0;}public void setLastNpcClickMs(long l){}public CIOClient getNetConnection(){return net;}public void sendPackets(String s){notice++;}}''')
    w('model/L1Inventory','''package l1j.server.server.model;import java.util.*;import l1j.server.server.model.Instance.*;public class L1Inventory {public static final int OK=0,MAX_AMOUNT=2000000000;public int adena=100000,limit=100,failConsume=-1,attempts,creates;public boolean storeReject;public Map<Integer,L1ItemInstance> keys=new HashMap<>();public boolean checkItem(int id){return !keys.isEmpty();}public boolean checkItem(int id,int n){return n>=0&&adena>=n;}public int checkAddItem(L1ItemInstance i,int n){return keys.size()<limit?0:1;}public boolean consumeItem(int id,int n){if(++attempts==failConsume||adena<n)return false;adena-=n;return true;}public L1ItemInstance getItem(int id){return keys.get(id);}public L1ItemInstance storeItem(L1ItemInstance i){if(storeReject)return null;keys.put(i.id,i);creates++;return i;}public L1ItemInstance storeItem(int id,int n){adena+=n;return null;}public L1ItemInstance[] findItemsId(int i){return keys.values().toArray(new L1ItemInstance[0]);}public int removeItem(L1ItemInstance i){return keys.remove(i.id,i)?1:0;}}''')
    w('model/L1AuctionTransaction','''package l1j.server.server.model;import l1j.server.server.model.Instance.*;import l1j.server.server.templates.*;public class L1AuctionTransaction {public static void bid(L1PcInstance p,int h,int a){p.bids++;}public static void list(L1PcInstance p,L1House h,int a){p.sells++;}}''')
    w('templates/L1House','''package l1j.server.server.templates;public class L1House {public int keeper=99;public int getKeeperId(){return keeper;}}''')
    w('datatables/HouseTable','''package l1j.server.server.datatables;import l1j.server.server.templates.*;public class HouseTable {public static HouseTable t=new HouseTable();public static HouseTable getInstance(){return t;}public L1House getHouseTable(int i){return i==1?new L1House():null;}}''')
    w('datatables/ItemTable','''package l1j.server.server.datatables;import l1j.server.server.model.*;import l1j.server.server.model.Instance.*;public class ItemTable {public static ItemTable t=new ItemTable();public int next=100;public boolean missing,stack;public static ItemTable getInstance(){return t;}public L1ItemInstance createItem(int id){if(missing)return null;L1ItemInstance i=new L1ItemInstance();i.id=++next;i.stack=stack;L1World.getInstance().objects.put(i.id,i);return i;}}''')
    w('model/npc/action/L1NpcAction','''package l1j.server.server.model.npc.action;import l1j.server.server.model.*;import l1j.server.server.model.Instance.*;public class L1NpcAction {public void dispatch(String s,L1PcInstance p,L1Object o,byte[] a,int n){p.xml++;}}''')
    w('datatables/NpcActionTable','''package l1j.server.server.datatables;import l1j.server.server.model.*;import l1j.server.server.model.Instance.*;import l1j.server.server.model.npc.action.*;public class NpcActionTable {public static NpcActionTable t=new NpcActionTable();public static NpcActionTable getInstance(){return t;}public L1NpcAction get(String s,L1PcInstance p,L1Object o){return new L1NpcAction();}public L1NpcAction get(L1PcInstance p,L1Object o){return null;}}''')
    w('model/network/utill/ConnectionState','''package l1j.server.server.model.network.utill;public enum ConnectionState{IN_GAME,OTHER}''')
    w('model/network/core/session/CIOClient','''package l1j.server.server.model.network.core.session;import l1j.server.server.model.Instance.*;import l1j.server.server.model.network.utill.*;import l1j.server.server.model.network.core.connection.*;public class CIOClient {public ConnectionState state=ConnectionState.IN_GAME;public L1PcInstance pc;public ConnectionState getConnectionState(){return state;}public L1PcInstance getActiveChar(){return pc;}public boolean isConnected(){return true;}public CUserSocket getConnection(){return null;}}''')
    w('model/network/core/connection/CUserSocket','''package l1j.server.server.model.network.core.connection;public class CUserSocket {public boolean isClientConnected(){return false;}public CIOFrame beginDirectFrame(int n){return null;}public boolean commitDirectFrame(CIOFrame f){return false;}public void abortDirectFrame(CIOFrame f){}}''')
    w('model/network/core/connection/CIOFrame','''package l1j.server.server.model.network.core.connection;import l1j.server.server.model.network.buffer.*;public class CIOFrame {public WriteBuffer buffer(){return null;}}''')
    w('model/network/buffer/WriteBuffer','''package l1j.server.server.model.network.buffer;public class WriteBuffer {public void writeC(int i){}public void writeD(int i){}public void writeH(int i){}public void writeS(String s){}}''')
    w('Opcodes','''package l1j.server.server;public class Opcodes {public static final int S_HYPERTEXT=1,S_HYPERTEXT_INPUT=2;}''')
    w('model/item/L1ItemId','''package l1j.server.server.model.item;public class L1ItemId {public static final int ADENA=40308;}''')
    w('model/character/skill/L1SkillId','''package l1j.server.server.model.character.skill;public class L1SkillId {}''')
    w('utils/CommonUtil','''package l1j.server.server.utils;import l1j.server.server.model.Instance.*;public class CommonUtil {public static void SetTodayDeleteTime(L1ItemInstance i,int n){}public static void SetHotelTownName(L1ItemInstance i,String s){}}''')
    for name,body in [('SC_SkillSound','public static void send(L1PcInstance p,int i,int n){}'),('SC_AuctionBoard','public static void sendAsync(L1PcInstance p,L1NpcInstance n){p.talks++;}'),('SC_NPCTalkReturn','')]:
        w('model/network/core/sc/packet/'+name,'package l1j.server.server.model.network.core.sc.packet;import l1j.server.server.model.Instance.*;public class '+name+'{'+body+'}')
    for name,body in [('Proto',''),('SC_MAP_TELEPORT_INFO_NOTI','public static void sendCreate(l1j.server.server.model.Instance.L1PcInstance p,int i,String[] a,int[] c,int n){}')]:
        w('packets/Protocol/MainServer/Proto/'+name,'package l1j.server.server.packets.Protocol.MainServer.Proto;public class '+name+'{'+body+'}')
    put('l1j/server/server/model/world/instance/dungeon/minigame/L1Gambling.java','''package l1j.server.server.model.world.instance.dungeon.minigame;import l1j.server.server.model.Instance.*;public class L1Gambling {public void dealerTrade(L1PcInstance p){}}''')
    put('l1j/server/server/model/world/instance/inn/loader/InnHelperLoader.java','''package l1j.server.server.model.world.instance.inn.loader;import l1j.server.server.model.Instance.*;public class InnHelperLoader {public static InnHelperLoader l=new InnHelperLoader();public boolean active;public static InnHelperLoader getInstance(){return l;}public boolean onResult(L1NpcInstance n,L1PcInstance p,String s,int a){if(active)p.inn++;return active;}public boolean onTalk(L1NpcInstance n,L1PcInstance p){if(active)p.inn++;return active;}}''')
    put('l1j/server/server/model/world/instance/inn/InnMapInfo.java','''package l1j.server.server.model.world.instance.inn;import java.util.concurrent.atomic.*;public class InnMapInfo {public String town="test";public AtomicInteger usageCount=new AtomicInteger();}''')
    put('l1j/server/server/model/world/instance/inn/InnRoom.java','''package l1j.server.server.model.world.instance.inn;import l1j.server.server.model.Instance.*;public class InnRoom {public static int rooms,keys;public static void create(InnMapInfo m,Integer[] ids){rooms++;keys+=ids.length;}public static void remove(L1ItemInstance i){}public static boolean input(L1ItemInstance[] i,L1PcInstance p){return false;}}''')
    w(P+'Check','''package l1j.server.server.model.network.core.cs.packet;
import l1j.server.server.model.*;import l1j.server.server.model.Instance.*;import l1j.server.server.model.network.utill.*;import l1j.server.server.model.network.core.session.*;import l1j.server.server.datatables.*;import l1j.server.server.model.world.instance.inn.*;import l1j.server.server.model.world.instance.inn.loader.*;
public class Check {static int cases,checks;static void ck(boolean c){checks++;if(!c)throw new AssertionError("case "+cases+" check "+checks);}public static void main(String[] a)throws Exception{
 for(int flags=0;flags<32;flags++)for(int dist:new int[]{-7,-6,0,6,7,Integer.MIN_VALUE,Integer.MAX_VALUE})for(int map:new int[]{1,2})for(int target=0;target<3;target++)for(boolean inn:new boolean[]{false,true}){
 cases++;var p=new L1PcInstance();var c=new CIOClient();c.pc=p;p.ghost=(flags&1)!=0;p.shop=(flags&2)!=0;p.unattended=(flags&4)!=0;p.autoclan=(flags&8)!=0;if((flags&16)!=0)c.state=ConnectionState.OTHER;var n=target==1?new L1AuctionBoardInstance():new L1NpcInstance();n.x=dist==Integer.MIN_VALUE||dist==Integer.MAX_VALUE?dist:100+dist;n.map=map;L1World.world.objects.clear();if(target!=2)L1World.world.objects.put(1,n);InnHelperLoader.l.active=inn;boolean allowed=flags==0&&dist>=-6&&dist<=6&&map==1&&target!=2;
 NpcTalkHandler.handle(c,1);ck(p.inn==(allowed&&inn?1:0));ck(p.talks==(allowed&&!inn?1:0));p.inn=0;
 CS_Amount.handle(c,1,100000,"agapply 1");ck(p.inn==(allowed&&inn?1:0));ck(p.bids==(allowed&&!inn&&target==1?1:0));p.inn=0;
 CS_Amount.handle(c,1,100000,"agsell 1");ck(p.sells==(allowed&&!inn?1:0));p.inn=0;CS_Amount.handle(c,1,1,"craft");ck(p.xml==(allowed&&!inn?1:0));}
 InnHelperLoader.l.active=false;
 for(String cmd:new String[]{"agapply 1"," AGAPPLY\\t1 extra","AgApPlY +1","agapply -1","agapply 0","agapply","agapply 2147483648","agsell 1","agsell 2","agsell -1","agsell 1 2","craft"})for(int amt:new int[]{-1,0,1,99999,100000,2000000000,Integer.MAX_VALUE}){
 cases++;var c=new CIOClient();var p=new L1PcInstance();c.pc=p;var n=new L1AuctionBoardInstance();L1World.world.objects.clear();L1World.world.objects.put(1,n);CS_Amount.handle(c,1,amt,cmd);boolean valid=amt>0&&amt<=2000000000;boolean bid=cmd.equals("agapply 1")||cmd.equals(" AGAPPLY\\t1 extra")||cmd.equals("AgApPlY +1");boolean sell=cmd.equals("agsell 1")||cmd.equals("agsell 1 2");ck(p.bids==(valid&&bid?1:0));ck(p.sells==(valid&&sell&&amt>=100000?1:0));ck(p.xml==(valid&&cmd.equals("craft")?1:0));}
 InnHelper.USAGECOUNT=3;
 for(int amt:new int[]{-1,0,1,2,20,21,1000000000,Integer.MAX_VALUE})for(boolean hall:new boolean[]{false,true})for(boolean crown:new boolean[]{false,true})for(boolean busy:new boolean[]{false,true})for(boolean existing:new boolean[]{false,true})for(int limit:new int[]{0,1,20})for(int mode=0;mode<5;mode++){
 cases++;L1World.world.objects.clear();ItemTable.t.missing=mode==1;ItemTable.t.stack=mode==2;var p=new L1PcInstance();p.crown=crown;p.busy=busy;p.inv.limit=limit;if(mode==3)p.inv.failConsume=1;if(existing){var item=new L1ItemInstance();item.id=77;p.inv.keys.put(77,item);L1World.world.objects.put(77,item);}var helper=InnHelper.create();var room=new InnMapInfo();var h=new InnMapInfo();if(mode==4)(hall?h:room).usageCount.set(3);helper.setMapInfo(new InnMapInfo[]{room,h});InnRoom.rooms=0;InnRoom.keys=0;helper.onResult(new L1NpcInstance(),p,hall?"inn12":"inn2",amt);int want=amt>=1&&amt<=20&&(!hall||crown)&&!busy&&!existing&&mode==0?Math.min(amt,limit):0;ck(p.inv.creates==want);ck(p.inv.adena==100000-want*(hall?600:300));ck(InnRoom.keys==want);ck(InnRoom.rooms==(want>0?1:0));ck(L1World.world.objects.size()==want+(existing?1:0));ck((hall?h:room).usageCount.get()==(mode==4?3:want>0?1:0));}
 System.out.println("PASS scenarios="+cases+" checks="+checks);}}
''')
    subprocess.run(['javac','--release','21','-encoding','UTF-8','-d',str(out),*map(str,src.rglob('*.java'))],check=True)
    subprocess.run(['java','-cp',str(out),'l1j.server.server.model.network.core.cs.packet.Check'],check=True)
